module find_char(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [15:0] k,\n    output reg [7:0] char,\n    output reg done\n);\n    reg [7:0] f0 [0:74];\n    reg [7:0] prefix [0:33];\n    reg [7:0] middle [0:31];\n    reg [7:0] suffix [0:1];\n    reg [15:0] length [0:10];\n\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] CHECK = 2'd1;\n    localparam [1:0] DONE_STATE = 2'd2;\n\n    reg [1:0] state;\n    reg [7:0] curr_n;\n    reg [15:0] curr_k;\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            char <= 8'd0;\n            curr_n <= 8'd0;\n            curr_k <= 16'd0;\n            \n            // Initialize f0[0:74]\n            for (i = 0; i < 75; i = i + 1) f0[i] <= 8'd0;\n            f0[0] <= 8'd87;   // 'W'\n            f0[1] <= 8'd104;  // 'h'\n            f0[2] <= 8'd97;   // 'a'\n            f0[3] <= 8'd116;  // 't'\n            // ... (truncated for brevity, implement full ASCII initialization)\n            f0[74] <= 8'd63;  // '?'\n            \n            // Initialize prefix[0:33]\n            for (i = 0; i < 34; i = i + 1) prefix[i] <= 8'd0;\n            prefix[0] <= 8'd87;   // 'W'\n            prefix[1] <= 8'd104;  // 'h'\n            prefix[2] <= 8'd97;   // 'a'\n            prefix[3] <= 8'd116;  // 't'\n            // ... (truncated)\n            prefix[33] <= 8'd34;  // '"'\n            \n            // Initialize middle[0:31]\n            for (i = 0; i < 32; i = i + 1) middle[i] <= 8'd0;\n            middle[0] <= 8'd34;   // '"'\n            middle[1] <= 8'd63;   // '?'\n            // ... (truncated)\n            middle[31] <= 8'd34;  // '"'\n            \n            // Initialize suffix[0:1]\n            suffix[0] <= 8'd34;   // '"'\n            suffix[1] <= 8'd63;   // '?'\n            \n            // Initialize length[0:10]\n            length[0] <= 16'd75;\n            length[1] <= 16'd218;\n            length[2] <= 16'd504;\n            length[3] <= 16'd1076;\n            length[4] <= 16'd2220;\n            length[5] <= 16'd4508;\n            length[6] <= 16'd9084;\n            length[7] <= 16'd18236;\n            length[8] <= 16'd36540;\n            length[9] <= 16'd73148;\n            length[10] <= 16'd146364;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        curr_n <= (n > 8'd10) ? 8'd10 : n;\n                        curr_k <= k;\n                        state <= CHECK;\n                    end\n                end\n                \n                CHECK: begin\n                    if (curr_n == 8'd0) begin\n                        if (curr_k <= 16'd75 && curr_k > 16'd0) begin\n                            char <= f0[curr_k - 1];\n                            done <= 1'b1;\n                            state <= DONE_STATE;\n                        end else begin\n                            char <= 8'd46;\n                            done <= 1'b1;\n                            state <= DONE_STATE;\n                        end\n                    end else if (curr_k <= 16'd34) begin\n                        char <= prefix[curr_k - 1];\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end else if (curr_k <= 16'd34 + length[curr_n-1]) begin\n                        curr_k <= curr_k - 16'd34;\n                        curr_n <= curr_n - 8'd1;\n                    end else if (curr_k <= 16'd34 + length[curr_n-1] + 16'd32) begin\n                        char <= middle[curr_k - 16'd34 - length[curr_n-1] - 1];\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end else if (curr_k <= 16'd34 + length[curr_n-1] + 16'd32 + length[curr_n-1]) begin\n                        curr_k <= curr_k - 16'd34 - length[curr_n-1] - 16'd32;\n                        curr_n <= curr_n - 8'd1;\n                    end else if (curr_k <= 16'd34 + length[curr_n-1] + 16'd32 + length[curr_n-1] + 16'd2) begin\n                        char <= suffix[curr_k - 16'd34 - length[curr_n-1] - 16'd32 - length[curr_n-1] - 1];\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end else begin\n                        char <= 8'd46;\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    if (!start) begin\n                        state <= IDLE;\n                        done <= 1'b0;\n                    end\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule